const GQ_EX={key:"gq_ex",title:"Exchange tracker",hint:"45-day identification and 180-day completion run from the relinquished-property closing (IRC §1031; Treas. Reg. 1.1031(k)-1) — the earlier of 180 days or the tax return due date incl. extensions",
 fields:[["n","Client"],["rel","Relinquished property"],["close","Relinquished closing","date"],["sale","Sale price","number","width:110px"],["debt","Debt paid off","number","width:110px"],["qi","Qualified intermediary"],["ids","Identified properties (; separated)"],["repl","Replacement price","number","width:120px"],["newdebt","New loan amount","number","width:120px"],["type",["Delayed (forward)","Reverse","Improvement / build-to-suit","Simultaneous"]]],
 prep:o=>{o.st="Open"},
 cols:[["Client",r=>`<b>${esc(r.n)}</b><div class="mut">${esc(r.rel)}</div>`],["Type",r=>esc(r.type)],["45-day ID",r=>{const d=gpDay(gpAddDays(r.close,45));return r.close?`${esc(gpAddDays(r.close,45))} ${gpBadge(d<0?"passed":d+" d",d<0?"#718096":d<=10?"#c53030":"#2f855a")}`:"—"}],["180-day close",r=>{const d=gpDay(gpAddDays(r.close,180));return r.close?`${esc(gpAddDays(r.close,180))} ${gpBadge(d<0?"passed":d+" d",d<0?"#718096":d<=30?"#c53030":"#2f855a")}`:"—"}],["ID rule",r=>{const ids=String(r.ids||"").split(";").filter(x=>x.trim());return ids.length<=3?gpFlag(true,"3-property"):gpFlag(false,ids.length+" ids — 200% or 95% rule applies")}],["Boot",r=>{const b=gqBoot(r);return b.total>0?`<span style="color:var(--bad)">${gpMoney(b.total)} taxable</span><div class="mut">cash ${gpMoney(b.cash)} · debt ${gpMoney(b.debt)}</div>`:gpFlag(true,"no boot")}],["QI",r=>esc(r.qi||"—")],["Status",r=>esc(r.st)]],
 actions:[gpCycle(["Open","Identified","In escrow","Closed","Failed"]),["Clock cards",r=>{gpCard(`🏦 1031 ID deadline: ${r.n}`,`Identify replacement(s) in writing to the QI by ${gpAddDays(r.close,45)} (45 days, no extensions)`,"1031 & Investor Finance Specialist","Needs Steven",Math.max(0,gpDay(gpAddDays(r.close,40))||0));gpCard(`🏦 1031 completion deadline: ${r.n}`,`Close replacement by ${gpAddDays(r.close,180)} or the tax-return due date if earlier`,"1031 & Investor Finance Specialist","Needs Steven",Math.max(0,gpDay(gpAddDays(r.close,165))||0));toast("Deadline cards added")}]],
 kpis:R=>[["Open exchanges",R.filter(r=>!/Closed|Failed/.test(r.st)).length],["ID deadline ≤10 d",R.filter(r=>{const d=gpDay(gpAddDays(r.close,45));return d!=null&&d>=0&&d<=10}).length],["Close deadline ≤30 d",R.filter(r=>{const d=gpDay(gpAddDays(r.close,180));return d!=null&&d>=0&&d<=30}).length],["With boot",R.filter(r=>gqBoot(r).total>0).length]]};
function gqBoot(r){const sale=+r.sale||0,debt=+r.debt||0,repl=+r.repl||0,nd=+r.newdebt||0;const equity=sale-debt;const cashIn=Math.max(0,repl-nd);const cash=Math.max(0,equity-cashIn);const debtRelief=Math.max(0,debt-nd-Math.max(0,cashIn-equity));const total=repl&&sale?Math.max(cash,0)+Math.max(debtRelief,0):0;return{cash:repl?cash:0,debt:repl?debtRelief:0,total}}
gpPage("ex1031","🏦","1031 Exchange & Investor Desk","45/180-day clocks · identification rules · boot · replacement financing","#2c7a7b",[
 ["track","📋 Exchanges",()=>gpRegHtml(GQ_EX),r=>gpRegMount(GQ_EX,r)],
 ["rules","📖 Rules",()=>`<div class="grid g2"><div class="card"><b>Timeline (no extensions except federally declared disasters)</b><ul class="sm"><li>Day 0: relinquished property closes; proceeds go straight to the Qualified Intermediary — never to the client</li><li>Day 45: written identification to the QI, signed by the taxpayer</li><li>Day 180 (or tax-return due date if earlier — file an extension): replacement must close</li><li>Like-kind = real property held for investment or business use; personal residence and flips don't qualify</li></ul></div><div class="card"><b>Identification rules</b><ul class="sm"><li><b>3-property rule:</b> up to 3 properties of any value</li><li><b>200% rule:</b> any number, total FMV ≤ 200% of relinquished value</li><li><b>95% rule:</b> any number/value, but must acquire 95% of the total identified</li></ul><b>Boot</b><ul class="sm"><li>Cash boot: equity not reinvested</li><li>Mortgage boot: debt relief not replaced by new debt or added cash</li><li>Full deferral: buy equal or greater value, reinvest all equity, replace all debt (or add cash)</li></ul></div><div class="card"><b>Variants</b><ul class="sm"><li><b>Reverse:</b> buy first via an Exchange Accommodation Titleholder (Rev. Proc. 2000-37); 45/180 still apply; financing the EAT is specialized — few lenders</li><li><b>Improvement:</b> improvements must be built within 180 days to count</li><li>Related-party exchanges: 2-year holding rule (§1031(f))</li><li>California clawback: CA tracks deferred gain on out-of-state replacement property — annual FTB 3840 filing</li></ul></div><div class="card sm mut">Coordinate with the client's CPA and QI on every exchange. This desk tracks dates and financing; it is not tax advice. Figures and rules: verify with IRS guidance and counsel.</div></div>`],
 ["finance","🏠 Replacement financing",()=>gpCheckHtml("gq_ex_fin",["Confirm loan type: DSCR (no personal income) vs conventional investor vs portfolio/commercial (5+ units)","Pre-approve before the 45-day ID so offers are credible","QI funds count as down payment — get the QI balance letter","Title must vest in the same taxpayer (or disregarded LLC) that sold","Reserves: conventional investor typically 6 months PITIA per financed property (verify DU); DSCR per lender matrix","Rent schedule (1007) or leases for rental income; DSCR ≥ 1.0–1.25 per lender","Appraisal timing: order day 1 of escrow — the 180-day clock doesn't wait","Lock strategy that survives a delayed close","Closing instructions: escrow pays the QI, not the client","Schedule the close before day 180 with a buffer of at least 10 days"],"Replacement financing checklist")],
 ["calc","🧮 Boot calculator",()=>`<div class="card"><div class="row" style="gap:6px;flex-wrap:wrap"><input id="gq_b_s" type="number" placeholder="Sale price"><input id="gq_b_d" type="number" placeholder="Debt paid off"><input id="gq_b_r" type="number" placeholder="Replacement price"><input id="gq_b_n" type="number" placeholder="New loan"><button class="btn sm" id="gq_b_go">Calculate</button></div><div id="gq_b_out" class="sm" style="margin-top:8px"></div></div>`,()=>{$("#gq_b_go").onclick=()=>{const b=gqBoot({sale:$("#gq_b_s").value,debt:$("#gq_b_d").value,repl:$("#gq_b_r").value,newdebt:$("#gq_b_n").value});$("#gq_b_out").innerHTML=b.total>0?`Taxable boot about <b>${gpMoney(b.total)}</b> (cash ${gpMoney(b.cash)} · debt relief ${gpMoney(b.debt)}). To defer fully, raise the replacement price or the new loan, or add cash. Confirm with the CPA.`:"No boot: all equity reinvested and debt replaced."}}]]);
