 rb:{k:"ex1031",n:"1031 exchange financing",cat:"Investor",when:"Investor client sells a rental; relinquished closing scheduled",steps:["Exchange tracker → add with relinquished closing date","Clock cards → Board (day 40 and day 165)","Pre-approve replacement financing before the 45-day ID","QI balance letter as assets","Close by day 170"],owner:"1031 & Investor Finance Specialist",backup:"Scenario Desk Agent",squad:"Investor Desk",kpi:["Exchanges that miss a deadline: 0"],guard:["Not tax advice — CPA and QI confirm"]},
 cv:[1,"1031 exchange & investor timelines","ex1031,dscr","1031 & Investor Finance Specialist","Scenario Desk Agent","Event: relinquished closing set","45/180 clocks, ID rule, boot, financing checklist → Board","CPA + QI confirm"],
