/* ================= 5. CLIENT EDUCATION HUB ================= */
const GQ_EDU={
 "First-time buyer":[["How pre-approval works","A pre-approval means a loan officer has reviewed your credit, income and savings and issued a letter showing how much you can borrow. Sellers take your offer more seriously with it. It isn't a final approval — the home still needs an appraisal and your situation must stay the same until closing."],["Your real budget","Lenders look at your monthly debts against your income. Your comfortable budget may be lower than the maximum — include property taxes, insurance, HOA and maintenance, not just the loan payment."],["Down payment options","Conventional loans start at 3% down for qualifying first-time buyers, FHA at 3.5%, VA and USDA at 0% for eligible buyers. Down-payment assistance programs like CalHFA may cover part of it."],["What not to do before closing","Don't change jobs, open new credit, finance furniture or a car, or move large sums of cash without telling your loan officer first. Each can delay or derail closing."],["Closing costs explained","Expect lender fees, title and escrow, appraisal, prepaid interest, and setting up your tax and insurance account. Your Loan Estimate lists them; sellers can contribute toward them."]],
 "Veteran":[["Your VA home loan benefit","VA loans let eligible veterans, service members and some surviving spouses buy with no down payment and no monthly mortgage insurance. The benefit can be used more than once."],["The funding fee","Most VA loans have a one-time funding fee that can be financed. Veterans with a VA disability rating are exempt — and refunds are possible if the rating comes after closing."],["Certificate of Eligibility","Your COE proves your entitlement. We can usually pull it online in minutes."],["Residual income","VA checks that you have enough money left each month after major expenses — a safeguard that's one reason VA loans perform well."],["Using BAH","Basic Allowance for Housing counts as income. On PCS orders, we can use the BAH at your new duty station."]],
 "Refinance":[["When a refinance makes sense","Compare the monthly savings against the costs to find your break-even month. If you'll stay past it, a refinance can pay off."],["Cash-out basics","A cash-out refinance replaces your loan with a bigger one and gives you the difference. It can fund improvements or pay off high-interest debt, but it increases what you owe."],["VA IRRRL","Veterans with a VA loan can often streamline-refinance to a lower rate with minimal paperwork and usually no appraisal."],["Shorter term","Moving from 30 to 15 years raises the payment but can save a large amount of interest."]],
 "Investor":[["DSCR loans","Debt-service-coverage loans qualify on the property's rent instead of your personal income — useful for self-employed investors and growing portfolios."],["Reserves","Investment loans require cash reserves for each financed property, usually several months of payments."],["1031 exchanges","Selling one rental and buying another within IRS deadlines can defer capital-gains tax. Talk to us and your CPA before you list."]],
 "Seller":[["Net proceeds","Your net is the sale price minus your loan payoff, commissions, transfer taxes, escrow and title fees, and any credits to the buyer."],["Buyer financing matters","An offer with a strong pre-approval and a reliable lender closes more often. Ask the buyer's lender for a call before accepting."],["Timeline","Most financed sales close in 21–45 days. Appraisal and inspection contingencies are the key dates to watch."]]};
const GQ_FAQ=[["Will checking my rate hurt my credit?","A hard credit pull can lower a score slightly. Multiple mortgage inquiries within a short window count as one for most scoring models."],["How much do I need for a down payment?","It depends on the program: 0% for VA and USDA, 3% for some conventional loans, 3.5% for FHA. Assistance programs can help."],["What credit score do I need?","Minimums vary by program and lender. Many programs work in the 600s; better scores usually mean better pricing."],["What's the difference between pre-qualified and pre-approved?","Pre-qualification is an estimate from what you tell us. Pre-approval verifies credit, income and assets and carries more weight."],["How long does closing take?","Typically 21–45 days after an accepted offer, depending on the loan and appraisal."],["Can I buy with student loans?","Yes. Lenders count a monthly payment for student loans even if they're deferred; the method depends on the program."],["Can I use gift money?","Usually yes, from an acceptable donor with a gift letter and documentation of the transfer."],["What is PMI?","Private mortgage insurance protects the lender when you put less than 20% down on a conventional loan. It can be removed later."],["Can I buy if I'm self-employed?","Yes. We typically use two years of tax returns, or bank-statement programs for some borrowers."],["What's escrow?","A neutral third party that holds funds and documents until closing. After closing, an escrow account may also pay your taxes and insurance."],["What are points?","Optional upfront fees that lower your interest rate. Whether they pay off depends on how long you keep the loan."],["What happens at the appraisal?","A licensed appraiser estimates the home's value for the lender. If it's low, you can renegotiate, pay the difference or challenge it with better comparables."],["Do I need a real estate agent?","Not legally, but a buyer's agent protects your interests. Under the 2024 rules you'll sign a written agreement before touring."],["Can I close remotely?","Often yes, with mobile notaries or remote online notarization where allowed. Some steps may still need wet signatures."],["What if rates drop after I buy?","You can refinance later if the savings justify the cost; VA borrowers may qualify for a streamlined IRRRL."],["Can I use my VA benefit twice?","Yes. Entitlement can be restored after a VA loan is paid off, and you may have remaining entitlement for a second loan."],["Is the VA funding fee required?","For most borrowers, yes, but it can be financed, and veterans with a service-connected disability rating are exempt."],["Does BAH count as income?","Yes, for military borrowers it's counted as income."],["What is a rate lock?","A guarantee of your rate for a set time while your loan closes. Extensions can cost extra."],["What's a Loan Estimate?","A standard three-page form you get within three business days of applying that shows your rate, payment and costs."],["What's a Closing Disclosure?","The final version of your loan terms and costs, which you receive at least three business days before closing."],["Can I buy a home with a past bankruptcy?","Often yes after a waiting period that depends on the program and type of bankruptcy."],["Can I buy a condo with an FHA or VA loan?","Yes if the project meets the program's approval requirements; we check that early."],["What is HOA review?","Lenders review a condo association's budget, reserves and insurance to make sure the project is financially sound."],["How do property taxes work in California?","Generally about 1% of purchase price plus local assessments, set when you buy under Proposition 13."],["Do I need flood insurance?","Required if the home is in a high-risk flood zone with a federally backed loan; recommended for many others."],["Why is homeowners insurance hard to get in parts of California?","Wildfire risk has led some insurers to stop writing policies. The FAIR Plan plus a wraparound policy is a fallback; start shopping early."],["What's a buydown?","Money paid upfront, often by the seller, to lower your rate for the first years or the life of the loan."],["Can my parents co-sign?","Many programs allow a non-occupant co-borrower; rules vary."],["Can I rent out my home later?","Usually after living there as required by your loan, often 12 months; check your loan's occupancy terms."],["What's a HELOC?","A home equity line of credit lets you borrow against your equity as needed, usually with a variable rate."],["Can I get a loan with 1099 income?","Yes, with two years of history in most cases, or with 1099-based programs."],["What documents should I gather?","Pay stubs, W-2s or tax returns, two months of bank statements, ID, and details on any other properties or debts."],["Why do you need explanations for deposits?","Lenders must verify the source of large deposits to make sure funds aren't borrowed."],["Will my payment change?","On a fixed-rate loan, principal and interest stay the same; taxes and insurance can change your total payment."],["What's an ARM?","An adjustable-rate mortgage has a fixed rate for an initial period, then adjusts with the market within caps."],["Can I pay my loan off early?","Most residential loans today have no prepayment penalty; check your note."],["Who is Vanessa?","Vanessa is Steven's AI assistant. She helps with scheduling and reminders and always tells you she's an AI. Steven personally handles your loan."],["How do I avoid wire fraud?","Never wire money based on emailed instructions alone. Call escrow at a number you already know to confirm before sending."],["Are you licensed?","Steven Shearrill is a licensed mortgage loan originator (NMLS 2449246) with Patriot Pacific Financial Corp (NMLS 1921615). Look us up at nmlsconsumeraccess.org."]];
const gqGrade=t=>{const w=String(t).split(/\s+/).filter(Boolean),s=String(t).split(/[.!?]+/).filter(x=>x.trim());const syl=w.reduce((a,x)=>a+Math.max(1,(x.toLowerCase().match(/[aeiouy]+/g)||[]).length),0);return w.length&&s.length?Math.max(0,+(0.39*(w.length/s.length)+11.8*(syl/w.length)-15.59).toFixed(1)):0};
